import React, { useEffect, useMemo, useState } from "react";
import ImageCarousel from "../Components/ImageCarousel";

const Gallery = ({ galleryImgData }) => {
  const [imgState, setImgState] = useState("villa");
  const [isRendered, setIsRendered] = useState(false);
  const [carouselItems, setCarouselItems] = useState({});

  const filteredImages = useMemo(
    () => galleryImgData.filter((img) => img.type === imgState),
    [galleryImgData, imgState],
  );

  useEffect(() => {
    const carousel = document.querySelector("#img-container");
    if (isRendered && carousel) {
      carousel.scrollIntoView({ block: "center" });
    }
  }, [isRendered]);

  const categories = [
    { key: "villa", label: "Villas" },
    { key: "room", label: "Rooms" },
    { key: "surroundings", label: "Surroundings" },
  ];

  return (
    <section
      id="gallery"
      className="mx-auto max-w-7xl px-4 py-24 sm:px-6 lg:px-8"
    >
      <div className="mb-10 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="text-sm uppercase tracking-[0.35em] text-amber-300">
            Gallery
          </p>
          <h2 className="text-3xl font-semibold text-white sm:text-4xl">
            A closer look at the experience.
          </h2>
        </div>
        <div
          className="flex flex-wrap gap-3"
          role="tablist"
          aria-label="Gallery categories"
        >
          {categories.map((category) => (
            <button
              key={category.key}
              type="button"
              role="tab"
              aria-selected={imgState === category.key}
              className={`rounded-full px-4 py-2 text-sm font-semibold transition ${
                imgState === category.key
                  ? "bg-amber-400 text-slate-950"
                  : "bg-white/10 text-slate-200 hover:bg-white/20"
              }`}
              onClick={() => setImgState(category.key)}
            >
              {category.label}
            </button>
          ))}
        </div>
      </div>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {filteredImages.map((item, index) => (
          <button
            key={item.id}
            type="button"
            onClick={() => {
              setCarouselItems({ item, index });
              setIsRendered(true);
            }}
            className="group overflow-hidden rounded-[1.5rem] border border-white/10 bg-slate-900/50 text-left shadow-glow"
          >
            <img
              src={item.img}
              alt={`${item.type} view`}
              className="h-64 w-full object-cover transition duration-500 group-hover:scale-105"
            />
          </button>
        ))}
      </div>

      {isRendered && (
        <ImageCarousel
          allImages={filteredImages}
          image={carouselItems}
          setIsRendered={setIsRendered}
        />
      )}
    </section>
  );
};

export default Gallery;
